// ==UserScript==
// @name         三角洲行动官方地图 AZ3 Helper
// @namespace    https://df.qq.com/
// @version      1.8.1
// @description  修复 AZ3 出生点筛选与重置按钮遮挡，显示出生关系，并补充大保险箱点位与开启状态对比图。
// @author       Codex
// @match        https://df.qq.com/cp/a20240729directory/*
// @run-at       document-idle
// @grant        none
// ==/UserScript==

(function () {
    'use strict';

    const INSTALL_FLAG = '__deltaForceAz3Installed';
    if (window[INSTALL_FLAG]) return;
    window[INSTALL_FLAG] = true;

    const categorySelectors = {
        my: '.nav-my .nav-list-item[data-name="密钥"]',
        qxj: '.nav-xxj .nav-list-item[data-name="清洗间"]',
        csd: '.nav-csd .nav-list-item[data-name="出生点"]',
    };

    const spawnNames = [
        '核东1',
        '核东2',
        '废水1',
        '废水2',
        '海边',
        '海处',
        '海办',
        '核西2',
        '科学院',
        '火电',
        '燃料厂',
        '处理厂',
        '石棺',
        '核西1',
    ];

    const spawnRelations = [
        { from: '石棺', to: '核西1', label: '互斥', type: 'exclusive', route: 'vertical-first' },
        { from: '核西1', to: '核西2', label: '不互斥', type: 'compatible' },
        { from: '火电', to: '核西2', label: '互斥', type: 'exclusive' },
        { from: '燃料厂', to: '处理厂', label: '互斥', type: 'exclusive' },
        { from: '废水1', to: '核东2', label: '互刷', type: 'co-spawn' },
        { from: '核东1', to: '海边', label: '互刷', type: 'co-spawn' },
    ];

    const randomSpawnGroups = [
        { names: ['废水2', '海处', '海办'], label: '随机三刷二' },
    ];

    const guaranteedSpawns = new Set(['科学院']);

    const relationStyles = {
        exclusive: { color: '#ffd400', dashArray: null },
        compatible: { color: '#45e0d0', dashArray: '10 8' },
        'co-spawn': { color: '#8cf06a', dashArray: null },
    };

    const largeSafePoints = [
        {
            id: 'fuel-tank',
            name: '燃料储罐大保险箱',
            x: 217345,
            y: -234547,
            comparisonKey: 'fuel-tank',
        },
        {
            id: 'tokamak-panel',
            name: '托卡马克面板大保险箱',
            x: 192197.3,
            y: -227136,
            comparisonKey: 'tokamak-panel',
        },
        {
            id: 'spent-fuel-pile',
            name: '乏燃料堆体大保险箱',
            x: 198136.8281,
            y: -242283.7813,
            comparisonKey: 'spent-fuel-pile',
        },
        {
            id: 'wastewater-purifier',
            name: '污水净化器大保险箱',
            x: 211217.4,
            y: -160051,
            comparisonKey: 'wastewater-purifier',
        },
        {
            id: 'stellarator-control-column',
            name: '仿星控制柱大保险箱',
            x: 216780.4,
            y: -174676,
            comparisonKey: 'stellarator-control-column',
        },
    ];
    const largeSafeIconDataUri = 'data:image/webp;base64,';
    const largeSafeComparisonDataUri = 'data:image/webp;base64,';

    let relationLayer = null;
    let relationMap = null;
    let relationSignature = '';

    let largeSafeSelected = false;
    let largeSafeMarkers = [];
    let largeSafeMap = null;
    let largeSafeLayerName = '';

    let scheduled = false;

    function installStyles() {
        if (document.getElementById('df-az3-spawn-styles')) return;

        const style = document.createElement('style');
        style.id = 'df-az3-spawn-styles';
        style.textContent = `
            .nav-option-ctn > .reset-choose {
                bottom: 8px !important;
            }

            .df-az3-spawn-name {
                position: absolute;
                left: 50%;
                bottom: 100%;
                z-index: 2;
                margin-bottom: 2px;
                padding: 1px 4px;
                transform: translateX(-50%);
                border: 1px solid rgba(255, 255, 255, 0.45);
                border-radius: 4px;
                background: rgba(12, 16, 20, 0.82);
                color: #fff;
                font-size: 12px;
                font-weight: 700;
                line-height: 18px;
                letter-spacing: 0;
                white-space: nowrap;
                pointer-events: none;
                text-shadow: 0 1px 2px #000;
            }

            .df-az3-spawn-guaranteed {
                display: inline-block;
                margin-left: 4px;
                padding: 0 3px;
                border-radius: 3px;
                background: #ffd400;
                color: #15191d;
                font-size: 10px;
                line-height: 15px;
                text-shadow: none;
                vertical-align: 1px;
            }

            .df-az3-relation-line {
                stroke-linecap: round;
                stroke-linejoin: round;
            }

            .leaflet-tooltip.df-az3-relation-label {
                padding: 2px 5px;
                border: 1px solid currentColor;
                border-radius: 4px;
                background: rgba(12, 16, 20, 0.88);
                box-shadow: 0 1px 4px rgba(0, 0, 0, 0.65);
                font-size: 12px;
                font-weight: 700;
                line-height: 18px;
                letter-spacing: 0;
                pointer-events: none;
            }

            .leaflet-tooltip.df-az3-relation-exclusive-label {
                color: #ffd400;
            }

            .leaflet-tooltip.df-az3-relation-compatible-label {
                color: #45e0d0;
            }

            .leaflet-tooltip.df-az3-relation-co-spawn-label {
                color: #8cf06a;
            }

            .leaflet-tooltip.df-az3-random-label {
                padding: 3px 7px;
                border: 1px solid #ff4fd8;
                border-radius: 4px;
                background: rgba(12, 16, 20, 0.9);
                box-shadow: 0 1px 4px rgba(0, 0, 0, 0.65);
                color: #ff72df;
                font-size: 13px;
                font-weight: 700;
                line-height: 18px;
                letter-spacing: 0;
                pointer-events: none;
            }

            .leaflet-tooltip.df-az3-relation-label::before,
            .leaflet-tooltip.df-az3-random-label::before {
                display: none;
            }

            .df-az3-large-safe-section .df-az3-large-safe-nav-icon {
                display: flex;
                align-items: center;
                justify-content: center;
                background-image: none !important;
                transform: none !important;
            }

            .df-az3-large-safe-section {
                display: flex;
                width: 3.3rem;
                margin-top: 0.1rem;
                overflow: hidden;
                flex-wrap: wrap;
                align-content: flex-start;
            }

            .df-az3-large-safe-section.close {
                height: 0.3rem;
            }

            .df-az3-large-safe-section .wz-bg {
                position: relative;
            }

            .df-az3-large-safe-section .wz-num {
                position: absolute;
                right: 2px;
                bottom: 2px;
                padding: 0 2px;
                border-radius: 2px;
                background: rgba(5, 12, 14, 0.82);
                font-size: 10px !important;
                line-height: 12px !important;
                transform: none !important;
            }

            .df-az3-large-safe-nav-icon img,
            .df-az3-large-safe-marker-image {
                display: block;
                width: 100%;
                height: 100%;
                object-fit: contain;
            }

            .df-az3-large-safe-map-icon {
                background: transparent;
                cursor: pointer;
            }

            .df-az3-large-safe-marker-image {
                filter: drop-shadow(0 1px 2px rgba(0, 0, 0, 0.85));
            }

            .df-az3-large-safe-dialog[hidden] {
                display: none !important;
            }

            .df-az3-large-safe-dialog {
                position: fixed;
                inset: 0;
                z-index: 1000000;
                display: flex;
                align-items: center;
                justify-content: center;
                padding: 24px;
                background: rgba(0, 0, 0, 0.82);
            }

            .df-az3-large-safe-dialog-content {
                position: relative;
                max-width: min(1000px, 92vw);
                max-height: 92vh;
                border: 1px solid rgba(255, 255, 255, 0.6);
                border-radius: 4px;
                background: #111;
                box-shadow: 0 12px 40px rgba(0, 0, 0, 0.75);
            }

            .df-az3-large-safe-dialog-image {
                display: block;
                max-width: min(1000px, 92vw);
                max-height: 92vh;
                border-radius: 3px;
                object-fit: contain;
            }

            .df-az3-large-safe-dialog-close {
                position: absolute;
                top: 8px;
                right: 8px;
                z-index: 1;
                width: 40px;
                height: 40px;
                padding: 0;
                border: 1px solid rgba(255, 255, 255, 0.75);
                border-radius: 4px;
                background: rgba(0, 0, 0, 0.72);
                color: #fff;
                font: 30px/36px Arial, sans-serif;
                letter-spacing: 0;
                cursor: pointer;
            }

            @media (max-width: 640px) {
                .df-az3-large-safe-dialog {
                    padding: 12px;
                }

                .df-az3-large-safe-dialog-content,
                .df-az3-large-safe-dialog-image {
                    max-width: calc(100vw - 24px);
                    max-height: calc(100vh - 24px);
                }
            }
        `;
        document.head.appendChild(style);
    }

    function isAz3Map() {
        return document.querySelector('.curr-map-name')?.textContent.trim().startsWith('AZ3') ?? false;
    }

    function getMarkerCategory(marker) {
        const src = marker.querySelector('img')?.src ?? '';
        return src.match(/\/(my|qxj|csd)\.png(?:[?#]|$)/i)?.[1].toLowerCase() ?? null;
    }

    const largeSafeTokamakComparisonDataUri = 'data:image/webp;base64,';
    const largeSafeSpentFuelComparisonDataUri = 'data:image/webp;base64,';
    const largeSafeWastewaterPurifierComparisonDataUri = 'data:image/webp;base64,';
    const largeSafeStellaratorControlColumnComparisonDataUri = 'data:image/webp;base64,';
    const largeSafeComparisonDataUris = {
        'fuel-tank': largeSafeComparisonDataUri,
        'tokamak-panel': largeSafeTokamakComparisonDataUri,
        'spent-fuel-pile': largeSafeSpentFuelComparisonDataUri,
        'wastewater-purifier': largeSafeWastewaterPurifierComparisonDataUri,
        'stellarator-control-column': largeSafeStellaratorControlColumnComparisonDataUri,
    };

    function isCategorySelected(category) {
        return document.querySelector(categorySelectors[category])?.classList.contains('active') ?? false;
    }

    function closeLargeSafeDialog() {
        const dialog = document.querySelector('.df-az3-large-safe-dialog');
        if (dialog) dialog.hidden = true;
    }

    function ensureLargeSafeDialog() {
        let dialog = document.querySelector('.df-az3-large-safe-dialog');
        if (dialog) return dialog;

        dialog = document.createElement('div');
        dialog.className = 'df-az3-large-safe-dialog';
        dialog.hidden = true;
        dialog.setAttribute('role', 'dialog');
        dialog.setAttribute('aria-modal', 'true');
        dialog.setAttribute('aria-label', '大保险箱开启状态对比');

        const content = document.createElement('div');
        content.className = 'df-az3-large-safe-dialog-content';

        const image = document.createElement('img');
        image.className = 'df-az3-large-safe-dialog-image';
        image.src = largeSafeComparisonDataUri;
        image.alt = '大保险箱未开启与已开启位置对比';

        const closeButton = document.createElement('button');
        closeButton.className = 'df-az3-large-safe-dialog-close';
        closeButton.type = 'button';
        closeButton.setAttribute('aria-label', '关闭');
        closeButton.textContent = '×';
        closeButton.addEventListener('click', closeLargeSafeDialog);

        content.append(image, closeButton);
        dialog.appendChild(content);
        dialog.addEventListener('click', (event) => {
            if (event.target === dialog) closeLargeSafeDialog();
        });
        document.body.appendChild(dialog);
        return dialog;
    }

    function openLargeSafeDialog(comparisonDataUri) {
        const dialog = ensureLargeSafeDialog();
        const image = dialog.querySelector('.df-az3-large-safe-dialog-image');
        if (image && comparisonDataUri) image.src = comparisonDataUri;
        dialog.hidden = false;
    }

    function syncLargeSafeNavItem(item) {
        if (!item) return;
        item.classList.toggle('active', largeSafeSelected);
        item.setAttribute('aria-pressed', String(largeSafeSelected));
    }

    function ensureLargeSafeNavSection() {
        const keySection = document.querySelector('.nav-my');
        const sectionList = keySection?.parentElement;
        if (!isAz3Map() || !keySection || !sectionList) {
            document.querySelector('.df-az3-large-safe-section')?.remove();
            return null;
        }

        keySection.querySelector('.df-az3-large-safe-item')?.remove();
        let section = sectionList.querySelector('.df-az3-large-safe-section');
        if (!section) {
            section = document.createElement('div');
            section.className = 'nav-type-item df-az3-large-safe-section';

            const heading = document.createElement('div');
            heading.className = 'fgx top0 type-item-fgx';
            heading.dataset.nav = 'df-az3-large-safe';
            heading.textContent = '大保险箱点位';
            heading.setAttribute('role', 'button');
            heading.setAttribute('tabindex', '0');
            heading.setAttribute('aria-expanded', 'true');

            const item = document.createElement('div');
            item.className = 'nav-list-item df-az3-large-safe-item red';
            item.dataset.name = '大保险箱';
            item.dataset.icon = 'df_az3_large_safe';
            item.dataset.filterKey = '大保险箱__helper';
            item.setAttribute('role', 'button');
            item.setAttribute('tabindex', '0');

            const iconBackground = document.createElement('div');
            iconBackground.className = 'wz-bg';

            const icon = document.createElement('div');
            icon.className = 'wz-icon df-az3-large-safe-nav-icon';
            const iconImage = document.createElement('img');
            iconImage.src = largeSafeIconDataUri;
            iconImage.alt = '';
            icon.appendChild(iconImage);

            const count = document.createElement('div');
            count.className = 'wz-num';
            count.textContent = String(largeSafePoints.length);

            const name = document.createElement('div');
            name.className = 'wz-name';
            name.textContent = '大保险箱';

            iconBackground.append(icon, count);
            item.append(iconBackground, name);

            const toggle = (event) => {
                if (event.type === 'keydown' && event.key !== 'Enter' && event.key !== ' ') return;
                event.preventDefault();
                event.stopImmediatePropagation();
                largeSafeSelected = !largeSafeSelected;
                syncLargeSafeNavItem(item);
                scheduleFilter();
            };
            item.addEventListener('click', toggle, true);
            item.addEventListener('keydown', toggle, true);

            const toggleSection = (event) => {
                if (event.type === 'keydown' && event.key !== 'Enter' && event.key !== ' ') return;
                event.preventDefault();
                event.stopImmediatePropagation();
                const collapsed = section.classList.toggle('close');
                heading.setAttribute('aria-expanded', String(!collapsed));
            };
            heading.addEventListener('click', toggleSection, true);
            heading.addEventListener('keydown', toggleSection, true);

            section.append(heading, item);
            keySection.after(section);
        }

        const item = section.querySelector('.df-az3-large-safe-item');
        syncLargeSafeNavItem(item);
        return section;
    }

    function clearLargeSafeMarkers() {
        largeSafeMarkers.forEach((marker) => {
            if (largeSafeMap?.hasLayer?.(marker)) largeSafeMap.removeLayer(marker);
        });
        largeSafeMarkers = [];
        largeSafeMap = null;
        largeSafeLayerName = '';
    }

    function updateLargeSafeMarkers() {
        if (!isAz3Map() || !largeSafeSelected || !window.map || !window.L || !window.getMapPos) {
            clearLargeSafeMarkers();
            return;
        }

        const layerName = window.currLayer?.name ?? '';
        const markersReady = largeSafeMap === window.map
            && largeSafeLayerName === layerName
            && largeSafeMarkers.length === largeSafePoints.length
            && largeSafeMarkers.every((marker) => largeSafeMap.hasLayer(marker));
        if (markersReady) return;

        clearLargeSafeMarkers();
        largeSafeMap = window.map;
        largeSafeLayerName = layerName;

        const icon = window.L.divIcon({
            className: 'df-az3-large-safe-map-icon',
            html: `<img class="df-az3-large-safe-marker-image" src="${largeSafeIconDataUri}" alt="">`,
            iconSize: [48, 48],
            iconAnchor: [24, 24],
        });

        largeSafeMarkers = largeSafePoints.flatMap((point) => {
            const position = window.getMapPos(point.x, point.y);
            if (!Number.isFinite(position?.x) || !Number.isFinite(position?.y)) return [];

            const marker = window.L.marker([position.y, position.x], {
                icon,
                keyboard: true,
                title: point.name,
                zIndexOffset: 1000,
            });
            marker.addTo(largeSafeMap);

            const comparisonDataUri = largeSafeComparisonDataUris[point.comparisonKey];

            const markerElement = marker.getElement();
            markerElement?.addEventListener('click', (event) => {
                event.preventDefault();
                event.stopImmediatePropagation();
                openLargeSafeDialog(comparisonDataUri);
            }, true);
            markerElement?.addEventListener('keydown', (event) => {
                if (event.key !== 'Enter' && event.key !== ' ') return;
                event.preventDefault();
                event.stopImmediatePropagation();
                openLargeSafeDialog(comparisonDataUri);
            }, true);
            return [marker];
        });
    }

    function getSpawnMarkers() {
        if (!window.cacheMarker) return [];

        return Object.values(window.cacheMarker).filter((marker) => {
            const element = marker?.getElement?.();
            return element && getMarkerCategory(element) === 'csd';
        });
    }

    function labelSpawnMarkers(spawnMarkers) {
        spawnMarkers.forEach((marker, index) => {
            const element = marker.getElement();
            const name = spawnNames[index];
            if (!element || !name) return;

            element.dataset.dfAz3SpawnName = name;
            let label = element.querySelector(':scope > .df-az3-spawn-name');
            if (!label) {
                label = document.createElement('span');
                label.className = 'df-az3-spawn-name';
                element.appendChild(label);
            }

            const isGuaranteed = guaranteedSpawns.has(name);
            if (
                label.dataset.spawnName !== name
                || label.classList.contains('df-az3-has-guaranteed') !== isGuaranteed
            ) {
                label.dataset.spawnName = name;
                label.classList.toggle('df-az3-has-guaranteed', isGuaranteed);
                label.replaceChildren(document.createTextNode(name));
                if (isGuaranteed) {
                    const badge = document.createElement('span');
                    badge.className = 'df-az3-spawn-guaranteed';
                    badge.textContent = '必刷';
                    label.appendChild(badge);
                }
            }
        });
    }

    function getRelationPoints(fromMarker, toMarker, route) {
        const fromPoint = fromMarker.getLatLng();
        const toPoint = toMarker.getLatLng();
        if (route === 'vertical-first') {
            return [fromPoint, window.L.latLng(toPoint.lat, fromPoint.lng), toPoint];
        }
        return [fromPoint, toPoint];
    }

    function drawArrowHead(startPoint, targetPoint) {
        const startPixel = relationMap.latLngToLayerPoint(startPoint);
        const targetPixel = relationMap.latLngToLayerPoint(targetPoint);
        const delta = targetPixel.subtract(startPixel);
        const length = Math.sqrt(delta.x * delta.x + delta.y * delta.y);
        if (!length) return;

        const unitX = delta.x / length;
        const unitY = delta.y / length;
        const baseX = targetPixel.x - unitX * 11;
        const baseY = targetPixel.y - unitY * 11;
        const wing = 5;
        const leftPixel = window.L.point(baseX - unitY * wing, baseY + unitX * wing);
        const rightPixel = window.L.point(baseX + unitY * wing, baseY - unitX * wing);
        const arrowPoints = [
            relationMap.layerPointToLatLng(leftPixel),
            targetPoint,
            relationMap.layerPointToLatLng(rightPixel),
        ];

        window.L.polyline(arrowPoints, {
            color: '#ff4fd8',
            weight: 3,
            opacity: 1,
            lineCap: 'round',
            lineJoin: 'round',
            interactive: false,
        }).addTo(relationLayer);
    }

    function clearRelationLayer() {
        if (relationLayer && relationMap?.hasLayer?.(relationLayer)) {
            relationMap.removeLayer(relationLayer);
        }
        relationLayer = null;
        relationMap = null;
        relationSignature = '';
    }

    function drawRelations(spawnMarkers) {
        if (!window.map || !window.L || spawnMarkers.length !== spawnNames.length) {
            clearRelationLayer();
            return;
        }

        const spawnsByName = new Map(
            spawnMarkers.map((marker, index) => [spawnNames[index], marker]),
        );
        const signature = spawnMarkers
            .map((marker, index) => `${spawnNames[index]}:${marker._leaflet_id}`)
            .join('|');

        if (
            relationLayer
            && relationMap === window.map
            && relationSignature === signature
            && relationMap.hasLayer(relationLayer)
        ) {
            return;
        }

        clearRelationLayer();
        relationMap = window.map;
        relationLayer = window.L.layerGroup().addTo(relationMap);
        relationSignature = signature;

        spawnRelations.forEach(({ from, to, label, type, route }) => {
            const fromMarker = spawnsByName.get(from);
            const toMarker = spawnsByName.get(to);
            if (!fromMarker || !toMarker) return;

            const points = getRelationPoints(fromMarker, toMarker, route);
            const style = relationStyles[type] ?? relationStyles.exclusive;

            window.L.polyline(points, {
                className: 'df-az3-relation-line',
                color: 'rgba(0, 0, 0, 0.78)',
                weight: 8,
                opacity: 0.9,
                dashArray: style.dashArray,
                interactive: false,
            }).addTo(relationLayer);

            window.L.polyline(points, {
                className: 'df-az3-relation-line',
                color: style.color,
                weight: 4,
                opacity: 1,
                dashArray: style.dashArray,
                interactive: false,
            })
                .bindTooltip(label, {
                    permanent: true,
                    direction: 'center',
                    className: `df-az3-relation-label df-az3-relation-${type}-label`,
                    opacity: 1,
                })
                .addTo(relationLayer);
        });

        randomSpawnGroups.forEach(({ names, label }) => {
            const markers = names.map((name) => spawnsByName.get(name)).filter(Boolean);
            if (markers.length !== names.length) return;

            const points = markers.map((marker) => marker.getLatLng());
            const labelPoint = window.L.latLng(
                points.reduce((sum, point) => sum + point.lat, 0) / points.length,
                Math.max(...points.map((point) => point.lng)) + 20,
            );
            const targetLatOffsets = [5, 0, -5];

            markers.forEach((marker, index) => {
                const targetPoint = window.L.latLng(
                    labelPoint.lat + targetLatOffsets[index],
                    labelPoint.lng,
                );

                window.L.polyline([marker.getLatLng(), targetPoint], {
                    color: '#ff4fd8',
                    weight: 3,
                    opacity: 1,
                    interactive: false,
                }).addTo(relationLayer);
                drawArrowHead(marker.getLatLng(), targetPoint);
            });

            window.L.tooltip({
                permanent: true,
                direction: 'right',
                offset: [12, 0],
                className: 'df-az3-random-label',
                opacity: 1,
            })
                .setLatLng(labelPoint)
                .setContent(label)
                .addTo(relationLayer);
        });
    }

    function updateSpawnAnnotations() {
        const shouldShow = isAz3Map() && isCategorySelected('csd');
        if (!shouldShow) {
            clearRelationLayer();
            return;
        }

        const spawnMarkers = getSpawnMarkers();
        labelSpawnMarkers(spawnMarkers);
        drawRelations(spawnMarkers);
    }

    function applyFilter() {
        scheduled = false;
        const az3Active = isAz3Map();

        ensureLargeSafeNavSection();

        document.querySelectorAll('.leaflet-marker-icon.map-icon').forEach((marker) => {
            const category = getMarkerCategory(marker);
            if (!category) return;

            const visible = !az3Active || isCategorySelected(category);
            if (visible) {
                marker.style.removeProperty('display');
                marker.removeAttribute('data-df-az3-filter-hidden');
            } else {
                marker.style.setProperty('display', 'none', 'important');
                marker.setAttribute('data-df-az3-filter-hidden', category);
            }
        });

        updateSpawnAnnotations();
        updateLargeSafeMarkers();
    }

    function scheduleFilter() {
        if (scheduled) return;
        scheduled = true;
        queueMicrotask(applyFilter);
    }

    const observer = new MutationObserver(scheduleFilter);
    observer.observe(document.body, {
        childList: true,
        subtree: true,
        attributes: true,
        attributeFilter: ['class'],
    });

    document.addEventListener('click', scheduleFilter, true);
    document.addEventListener('keydown', (event) => {
        if (event.key === 'Escape') closeLargeSafeDialog();
    });
    installStyles();
    scheduleFilter();
})();
